const {chromium}=require('./browser/node_modules/playwright');
const fs=require('fs');
const base='http://127.0.0.1:4183', out={checks:[],errors:[],issues:[]};
(async()=>{const b=await chromium.launch();const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.on('pageerror',e=>out.errors.push(e.message));p.on('response',r=>{if(r.status()>=500)out.errors.push(r.status()+' '+r.url())});
const check=(name,data)=>{out.checks.push({name,data});console.log(name,JSON.stringify(data))};
try{
 const data=await (await c.request.get(base+'/api/dracula/bootstrap?lang=ro')).json();check('bootstrap',{products:data.products.map(x=>({id:x.external_id,price:x.price})),categories:data.categories,pages:data.pages.length,demo:data.demo,languages:data.languages});
 for(const lang of ['ro','en','de']){await p.goto(base+'/'+lang+'/collection');await p.locator('.filters').waitFor();check('language '+lang,{html:await p.locator('html').getAttribute('lang'),title:await p.locator('h1').textContent(),categories:await p.locator('.filters').allTextContents(),products:await p.locator('.product h3').allTextContents()});for(const filter of ['stafide-naturale','stafide-aromatizate','all']){await p.locator('[data-filter="'+filter+'"]').click();check('filter '+lang+' '+filter,{count:await p.locator('.product').count(),text:(await p.locator('main').innerText()).slice(-250)})}}
 for(const width of [320,390,768,1440]){await p.setViewportSize({width,height:900});for(const path of ['/ro/','/ro/collection','/ro/product/alune-de-padure-dracula-farm','/ro/account','/de/collection']){await p.goto(base+path);await p.locator('#app[aria-busy=false]').waitFor();await p.evaluate(()=>document.fonts.ready);check('viewport '+width+' '+path,await p.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,unlabeled:[...document.querySelectorAll('button')].filter(x=>!x.textContent.trim()&&!x.getAttribute('aria-label')).length,brokenImgs:[...document.images].filter(i=>i.complete&&!i.naturalWidth).map(i=>i.src)})));}}
 await p.setViewportSize({width:1440,height:1000});
 for(const lang of ['ro','en','de'])for(const page of data.pages){await p.goto(base+'/'+lang+'/pages/'+page.slug);await p.locator('.legal-body').waitFor();check('footer '+lang+' '+page.slug,{h1:await p.locator('h1').textContent(),body:(await p.locator('.legal-body').innerText()).length,unresolved:/\{\{|undefined|\[object/.test(await p.locator('main').innerText())})}
 await p.goto(base+'/ro/account');await p.locator('[name=email]').fill('client@dracula-food.com');await p.locator('[name=password]').fill('Dracula121.');await p.locator('form button[type=submit]').click();await p.locator('[data-action=logout]').waitFor();check('client login',await p.locator('h1').textContent());
 await p.goto(base+'/ro/collection');await p.locator('.product').first().waitFor();const fav=p.locator('[data-action=favorite]').first(), orig=await fav.getAttribute('aria-pressed');await fav.click();await p.waitForTimeout(350);check('favorite toggle',{before:orig,after:await p.locator('[data-action=favorite]').first().getAttribute('aria-pressed')});await p.reload();await p.locator('.product').first().waitFor();check('favorite persisted',await p.locator('[data-action=favorite]').first().getAttribute('aria-pressed'));await p.locator('[data-action=favorite]').first().click();
 await p.locator('[data-action=add]').first().click();await p.waitForTimeout(350);await p.goto(base+'/ro/bag');await p.locator('.bag-row').waitFor();check('cart',await p.locator('.bag-row').innerText());const itemLink=await p.locator('.bag-row h3 a').getAttribute('href');await p.goto(base+itemLink);await p.locator('#app[aria-busy=false]').waitFor();check('bag product link',{url:itemLink,hasDetail:await p.locator('.product-detail').count()});
 await p.goto(base+'/ro/checkout');await p.locator('[name=first_name]').waitFor();for(const [key,value] of Object.entries({first_name:'Audit',last_name:'Independent Food',phone:'0722123456',line1:'QA Audit Demo 1',city:'Brasov',county:'Brasov',postal_code:'500001',notes:'QA independent food audit; demo only'}))await p.locator('[name='+key+']').fill(value);await p.locator('[name=accept_terms]').check();await p.locator('form button[type=submit]').click();await p.waitForTimeout(900);check('checkout',{url:p.url(),h1:await p.locator('h1').textContent(),errors:await p.locator('.form-error').allTextContents(),text:(await p.locator('main').innerText()).slice(0,600)});
 await p.goto(base+'/ro/account');await p.locator('[data-action=logout]').waitFor();check('order history',await p.locator('.order-card').allTextContents());await p.locator('[data-action=order]').first().click();check('order detail',await p.locator('.order-info').innerText());await p.keyboard.press('Escape');
 const api=async(path,method='GET',body)=>await p.evaluate(async({path,method,body})=>{const csrf=decodeURIComponent(document.cookie.split('; ').find(x=>x.startsWith('dracula_food_csrf='))?.split('=').slice(1).join('=')||'');const r=await fetch(path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body?JSON.stringify(body):undefined});return {status:r.status,data:await r.json().catch(()=>({}))}}, {path,method,body});
 check('client cannot admin',await api('/api/admin/products'));check('demo stripe blocked',await api('/api/payments/stripe/session','POST',{order_number:'QA'}));
 await p.locator('[data-action=logout]').click();await p.locator('[name=email]').waitFor();check('logout profile',await api('/api/account/profile'));
 await p.goto(base+'/admin/login?ui=classic');await p.locator('input[type=email]').fill('admin@dracula-food.com');await p.locator('input[type=password]').fill('Dracula121.');await p.locator('[data-testid=login-submit]').click();await p.waitForTimeout(900);
 for(const path of ['products','categories','orders','customers','legal-pages','translations','inquiries','settings','users']){await p.goto(base+'/admin/'+path+'?ui=classic');await p.waitForTimeout(450);check('admin '+path,{h1:await p.locator('h1').allTextContents(),body:(await p.locator('body').innerText()).slice(-500)})}
 await p.screenshot({path:'outputs/dracula-food/audit-admin.png',fullPage:true});
}catch(e){out.issues.push(e.stack);console.error(e)}finally{fs.writeFileSync('work/audit-food-results.json',JSON.stringify(out,null,2));await b.close()}})();
